import { Link } from "react-router-dom";
import { useEffect, useState } from "react";
import { api, money } from "@/lib/api";
import { ArrowRight, Sparkles, Truck, ShieldCheck, Star } from "lucide-react";

export default function Home() {
  const [products, setProducts] = useState([]);
  const [cats, setCats] = useState([]);
  useEffect(() => {
    api.get("/shop/products?limit=8").then((r) => setProducts(r.data)).catch(() => {});
    api.get("/shop/categories").then((r) => setCats(r.data)).catch(() => {});
  }, []);
  return (
    <div>
      <section className="relative overflow-hidden border-b border-black/5 bg-gradient-to-br from-white via-brand-50 to-white">
        <div className="mx-auto grid max-w-6xl gap-10 px-6 py-16 lg:grid-cols-2 lg:py-24">
          <div>
            <span className="inline-flex items-center gap-1.5 rounded-full bg-white px-3 py-1 text-xs font-semibold text-brand-600 shadow-sm">
              <Sparkles className="h-3.5 w-3.5" /> Novos vendedores toda semana
            </span>
            <h1 className="mt-5 font-display text-4xl font-extrabold sm:text-5xl">
              O marketplace com <span className="text-brand-500">tudo o que você precisa</span>,
              pago do jeito LEAMSE.
            </h1>
            <p className="mt-4 text-base text-ink-500">
              Milhares de produtos de vendedores verificados. Pagamento seguro,
              entrega rastreada e suporte que responde de verdade.
            </p>
            <div className="mt-6 flex flex-wrap gap-3">
              <Link to="/shop" className="inline-flex items-center gap-2 rounded-full bg-brand-500 px-6 py-3 font-semibold text-white shadow-lg shadow-brand-500/25 hover:bg-brand-600" data-testid="home-shop-cta">
                Explorar loja <ArrowRight className="h-4 w-4" />
              </Link>
              <Link to="/register" className="inline-flex items-center gap-2 rounded-full border border-black/10 bg-white px-6 py-3 font-semibold hover:bg-black/5" data-testid="home-sell-cta">
                Quero vender
              </Link>
            </div>
            <div className="mt-8 flex flex-wrap gap-6 text-xs text-ink-500">
              <span className="inline-flex items-center gap-1.5"><Truck className="h-4 w-4 text-brand-500"/> Frete para todo o Brasil</span>
              <span className="inline-flex items-center gap-1.5"><ShieldCheck className="h-4 w-4 text-brand-500"/> Pagamento protegido</span>
              <span className="inline-flex items-center gap-1.5"><Star className="h-4 w-4 text-brand-500"/> Avaliação real dos vendedores</span>
            </div>
          </div>
          <div className="relative hidden lg:block">
            <div className="absolute inset-0 rounded-3xl bg-brand-500/10 blur-3xl" />
            <div className="relative grid grid-cols-2 gap-4">
              {products.slice(0, 4).map((p, i) => (
                <Link key={p.id} to={`/product/${p.id}`}
                      className={`rounded-2xl border border-black/5 bg-white p-4 shadow-sm ${i%2? "mt-8":""}`}>
                  <div className="aspect-square overflow-hidden rounded-xl bg-brand-50">
                    {p.image_url && <img src={p.image_url} alt={p.name} className="h-full w-full object-cover" />}
                  </div>
                  <p className="mt-3 line-clamp-1 text-sm font-medium">{p.name}</p>
                  <p className="text-sm font-bold text-brand-600">{money(p.price_cents, p.currency)}</p>
                </Link>
              ))}
            </div>
          </div>
        </div>
      </section>

      {cats.length > 0 && (
        <section className="border-b border-black/5">
          <div className="mx-auto max-w-6xl px-6 py-10">
            <h2 className="font-display text-lg font-bold">Categorias</h2>
            <div className="mt-4 flex flex-wrap gap-2">
              {cats.map((c) => (
                <Link key={c} to={`/shop?cat=${encodeURIComponent(c)}`}
                      className="rounded-full border border-black/10 bg-white px-4 py-2 text-sm hover:border-brand-500 hover:text-brand-600">
                  {c}
                </Link>
              ))}
            </div>
          </div>
        </section>
      )}

      <section className="mx-auto max-w-6xl px-6 py-12">
        <div className="flex items-end justify-between">
          <h2 className="font-display text-2xl font-extrabold">Em destaque</h2>
          <Link to="/shop" className="text-sm font-medium text-brand-600 hover:underline">Ver tudo</Link>
        </div>
        <div className="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-4" data-testid="home-featured">
          {products.map((p) => <ProductCard key={p.id} p={p} />)}
          {products.length === 0 && (
            <p className="col-span-full py-12 text-center text-sm text-ink-500">
              Nenhum produto ainda. Seja o primeiro vendedor —{" "}
              <Link to="/register" className="font-medium text-brand-600 hover:underline">criar conta de vendedor</Link>
            </p>
          )}
        </div>
      </section>
    </div>
  );
}

export function ProductCard({ p }) {
  return (
    <Link to={`/product/${p.id}`} data-testid={`product-card-${p.id}`}
          className="group flex flex-col overflow-hidden rounded-2xl border border-black/5 bg-white transition hover:shadow-lg">
      <div className="relative aspect-square overflow-hidden bg-brand-50">
        {p.image_url
          ? <img src={p.image_url} alt={p.name} className="h-full w-full object-cover transition group-hover:scale-105" />
          : <div className="grid h-full place-items-center text-4xl text-brand-500 font-display">🛍️</div>}
      </div>
      <div className="flex flex-1 flex-col p-4">
        <p className="line-clamp-2 text-sm font-medium">{p.name}</p>
        <p className="mt-1 text-xs text-ink-500">por {p.seller_name}</p>
        <p className="mt-auto pt-3 font-display text-lg font-extrabold text-brand-600">
          {money(p.price_cents, p.currency)}
        </p>
      </div>
    </Link>
  );
}
